# Code generated by Claude
"""
The bench region stance selection on a moved layout (David 2026-10-25): the beaker and the hotplate shifted 15 cm along the bench (same spacing, toward the end farther from the bench legs: the legs
stand at x = +-2.0 and the objects at x = 0.8 and 1.0, so toward smaller x), the plan "navigate to the beaker, pick it up, navigate to the hotplate, place it" (stance selected by the bench region)
from selection to the placed beaker, recorded and replayed bit-identically.

    MUJOCO_GL=egl python experiments/stance_select_moved_test.py

Steps: (1) the full check's scene gets the moved layout (apply_stance_selection passes task_cfg); (2) the selection (stance, distance from TASK_CFG's, pedestal run, region counts, full check verdict);
(3) the pipeline episode on the moved scene; (4) the replay. Writes data/stance_select_moved_report.json. If the episode fails the failing step and reason are printed; no setting is tuned.
"""

import gc
import json
import os
import shutil
import sys
import tempfile
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.full_check import FullCheck  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402

SHIFT_X = -0.15
MOVED = {**TASK_CFG, "beaker_xy": (TASK_CFG["beaker_xy"][0] + SHIFT_X, TASK_CFG["beaker_xy"][1]), "hotplate_xy": (TASK_CFG["hotplate_xy"][0] + SHIFT_X, TASK_CFG["hotplate_xy"][1])}
results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def main():
    print(f"moved layout: beaker {MOVED['beaker_xy']}, hotplate {MOVED['hotplate_xy']} (TASK_CFG: {TASK_CFG['beaker_xy']}, {TASK_CFG['hotplate_xy']})", flush=True)
    print("1. the full check's scene is the moved layout", flush=True)
    fc = FullCheck(task_cfg=MOVED)
    bq = fc.scene_data.qpos[fc.model.joint("task_beaker_free").qposadr[0]:][:2]
    hp = fc.model.body_pos[fc.model.body("task_hotplate").id][:2]
    check("the beaker and the hotplate of the full check's scene are at the moved positions", np.allclose(bq, MOVED["beaker_xy"], atol=1e-6) and np.allclose(hp, MOVED["hotplate_xy"], atol=1e-6), f"beaker {np.round(bq, 3).tolist()} hotplate {np.round(hp, 3).tolist()}")
    del fc
    gc.collect()

    print("\n2. the selection on the moved layout", flush=True)
    t0 = time.perf_counter()
    task = make_pipeline_task(PLAN4, task_cfg=MOVED)
    t_sel = time.perf_counter() - t0
    gc.collect()
    rep = task["stance_selection"]
    run = rep["runs"][0]
    st = run["stance"]
    d = float(np.hypot(*(np.array(st["xy"]) - np.array(TASK_CFG["staging_xy"]))))
    fcr = run["full_check"][-1]
    first = run["ranked"][0]
    same = abs(first["xy"][0] - st["xy"][0]) < 1e-9 and abs(first["xy"][1] - st["xy"][1]) < 1e-9 and abs(first["q"] - st["q"]) < 1e-9
    print(f"  chosen stance {np.round(st['xy'], 3).tolist()} pedestal {st['q']} (TASK_CFG's {TASK_CFG['staging_xy']} pedestal {TASK_CFG['pedestal_q']}): {1000 * d:.0f} mm from TASK_CFG's, {1000 * (st['xy'][0] - TASK_CFG['staging_xy'][0]):.0f} mm in x\n"
          f"  region counts {run['counts']}, score {run['score']}, pedestal run of the overlay's best spot {run['overlay_run_q']} (the chosen stance is the overlay's best: {same})\n"
          f"  full check {[(np.round(t['xy'], 3).tolist(), t['q'], t.get('full_check_ok'), t.get('failed')) for t in run['full_check']]}\n  selection time {t_sel:.1f} s", flush=True)
    check("a stance was chosen and passed the full check", fcr.get("full_check_ok") is True, f"{fcr.get('failed')}")
    check("the region and the full check agree on the chosen stance (counts above zero for both objects, full check passes on the first ranked stance)", all(v > 0 for v in run["counts"].values()) and same and len(run["full_check"]) == 1, f"{run['counts']}, {len(run['full_check'])} full check(s)")
    check("one run, the second navigation step is null", len(rep["runs"]) == 1 and rep["null_nav"] == [2] and run["steps"] == [1, 3], f"{rep['null_nav']}")

    print("\n3. the pipeline on the moved scene", flush=True)
    sim = load_task(MOVED, cameras=True)
    out = Path(tempfile.mkdtemp(prefix="stance_moved_"))
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", record_dir=out / "recording")
    state = task["pipeline"]["orchestrator"]["state"]
    print(f"  outcome {s['outcome']}; plan failure {state['failure']}; status {state['status']}")
    check("the episode outcome is SUCCESS", s["outcome"] == "SUCCESS", f"{s['outcome']}; failure {state['failure']}")
    check("the plan finished, every segment done", state["finished"] and all(x == "done" for x in state["status"]) and len(state["status"]) == 4, f"{state['status']}")
    srep = task["pipeline"]["navigation"]["report"]()
    a = srep.get("arrival_at_end_of_drive") or {}
    h = srep.get("base_pose_error_at_handoff") or {}
    print(f"  arrival {a}; handoff {h}")
    check("the staging arrived within 1 cm and 1 degree at the chosen stance", bool(a) and bool(h) and a["pos_err_mm"] <= 10.0 and abs(a["yaw_err_deg"]) <= 1.0 and h["pos_err_mm"] <= 10.0)
    ok, diag = task["check_success"](sim.model, sim.data)
    check("the beaker stands on the hotplate", ok, str({k: diag[k]["ok"] for k in diag if isinstance(diag[k], dict) and "ok" in diag[k]}))

    print("\n4. the replay", flush=True)
    del sim, task
    gc.collect()
    r = replay_run(out / "recording", video="none", quiet=True)
    check("the replay is bit-identical", r["ok"], f"{r['ticks']} ticks, mismatch {r['mismatch']}")
    keep = PROJECT_ROOT / "data" / "stance_select_moved_report.json"
    tmp = keep.with_suffix(".tmp")
    tmp.write_text(json.dumps({"layout": {"beaker_xy": MOVED["beaker_xy"], "hotplate_xy": MOVED["hotplate_xy"]}, "selection": rep, "select_seconds": t_sel, "outcome": s["outcome"], "failure": state["failure"], "status": state["status"],
                               "arrival": a, "handoff": h, "distance_from_task_cfg_m": d}, indent=1, default=str))
    tmp.replace(keep)
    shutil.rmtree(out, ignore_errors=True)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
